cells.counterexample:
class Sink
  private _o: Object?;
  public method Keep(o: Object?)
    _o := o;                      // plain parameter: field-store residual
  end Keep;
end Sink;
static class Demo
  public static method Run(sink: Sink)
    do
      var a: Array<int> := [1, 2, 3];
      var s: IReadOnlySpan<int> := a.AsSpan();  // admitted: declared IReadOnlySpan
      if s is Object then         // §12.7: reference operand, ordinary run-time test;
        sink.Keep(s);             //   s is flow-narrowed to Object in the block
      end;                        // reading 2: Object to Object, nothing converted,
    end;                          //   no §9.7 bullet reached; a disposed here,
  end Run;                        //   sink._o boxes a span over it
end Demo;
// Reading 1: s is read "by its declared type" as the span, so Keep(s) is the
// borrow-erasing conversion: rejected. Generic twin (Keep<Object>):
//   if x is T then _v := x; end;   over x: IReadOnlySpan<int>

class Item public method N(): int => 1; end Item;
class Sink
  private _o: Object?;
  public method Keep(o: Object?)
    _o := o;                      // plain parameter: field-store residual
  end Keep;
end Sink;
static class Demo
  public static method Run(sink: Sink)
    do
      using var it := new Item();
      var f: () -> int := lambda() => it.N();   // source set {it}
      if f is Object then         // f flow-narrowed to Object (§12.7)
        sink.Keep(f);             // reading 2: no implicit conversion is written,
      end;                        //   so no set-erasing position is reached
    end;                          // it disposed; sink._o holds a closure over it,
  end Run;                        //   and `sink._o as () -> int` reads back with
end Demo;                         //   the empty set (provenance clause 5)
// Reading 1: f's read carries {it} (clause 6) to a position declared Object:
// set-erasing, rejected. `var o: Object := f`, `f as Object` and
// `case f of o: Object` are rejected under both readings.

class Probe<T>
  private _o: Object?;
  public method Keep(v: T)
    if v is Object then   // flow-narrowed to Object (§12.7)
      _o := v;            // Object to Object: no conversion written
    end;
  end Keep;
end Probe;
static class Demo
  public static method Run(p: Probe<IReadOnlySpan<int>>)
    do
      var a: Array<int> := [1, 2, 3];
      p.Keep(a.AsSpan());
    end;   // reading 2: p._o boxes a span over the dead `a`
  end Run;
end Demo;
// Reading 1: the store reads v at its declared type T, the span at this
// substitution (§9.7's instance-field bullet, generic reading): rejected
// wherever Probe<IReadOnlySpan<int>> is named.

routes.counterexample:
class Box<T>
  public V: T;
  public method Hand(): Object => lambda(b: Box<T>) => b.V;  // capture-free: admitted at Object
end Box;

// caller, at T = Task:
method Use(box: Box<Task>)
  var f := box.Hand() as (Box<Task>) -> Task;  // §12.7 identity: formed type matches, test succeeds
  using var t := f(box);                       // invocation keyed on `Task` return: a mint, adopted
end Use;                                       // t disposed here while box.V still holds it
